console.log('Inventory now:', JSON.stringify(lib.inv()));
bot.chat(`delta: Base report: Health: ${bot.health}/20, Food: ${bot.food}/20, Water bucket: ${lib.count('water_bucket')}. Holding ${lib.count('iron_ingot')} iron ingots.`);

