      { x: 61.5, y: 67, z: -70 },
      { x: 61.5, y: 67, z: -75 },
      { x: 62.0, y: 67, z: -80 },
      { x: 61, y: 66, z: -100 },
      { x: 50, y: 65, z: -115 },
      { x: 44, y: 65, z: -127 }
    ];

    let startIdx = 0;
    for (let i = 0; i < waypoints.length; i++) {
      const wp = waypoints[i];
      if (bot.entity.position.distanceTo(new Vec3(wp.x, wp.y, wp.z)) < 3.5) {
