      } catch (e) {}
    }
  }

  // Clear fire ahead
  await globalThis.clearFireAhead();

  // Move forward
  bot.setControlState('forward', true);
  if (bot.entity.isCollidedHorizontally) {
    bot.setControlState('jump', true);
    await sleep(250);
    bot.setControlState('jump', false);
